(() => {
  // Deterministic safeguard for resolve_conversation()'s 2h inactivity
  // timeout: persist conversations.last_message_at from the inbound
  // message row just inserted by `insert message`, so timing stays
  // correct even if the DB AFTER INSERT trigger did not take effect.
  // Prefer the persisted row's real created_at; fall back to the
  // insert instant. Does NOT change lifecycle/handover behaviour.
  const resp = $node["insert message"].json;
  const row = Array.isArray(resp) ? (resp[0] || {}) : (resp || {});
  const ts = row.created_at || new Date().toISOString();
  return { last_message_at: ts };
})()
}}

